mapper.select:
SELECT STD_VAL FROM TB_SY_OPER_STD WHERE STD_CD=#{code}
  AND APLY_BGN_YM <= to_char(current_timestamp AT TIME ZONE 'Asia/Seoul','YYYYMM')
ORDER BY APLY_BGN_YM DESC LIMIT 1

SELECT p.DEV_ID AS "developerId",p.MON_PAY_AMT AS "amount" FROM TB_HR_DEV_PRC p
WHERE p.MON_PAY_AMT IS NOT NULL AND p.APLY_BGN_YM <= #{month}
  AND (p.APLY_END_YM IS NULL OR p.APLY_END_YM >= #{month})
